pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint blockNumber, uint blockTimestamp) public {
        // We want to test fallback with a revert condition that does not send ether: block.number % 15 != 0
        // Bound inputs to avoid underflow and ensure block.timestamp > pastBlockTime initially
        vm.assume(blockNumber % 15 != 0);
        vm.assume(blockTimestamp > c.pastBlockTime());
        vm.warp(blockTimestamp);
        // Record pastBlockTime before call
        uint before = c.pastBlockTime();
        // Prepare a call that will revert (msg.value != 10 ether) so we can test the no-update case
        // Actually we want a call that does NOT revert, but also does not send because block.number % 15 != 0
        // So we use msg.value == 10 ether, but block.number % 15 != 0, so the require passes but the if fails.
        vm.deal(address(this), 10 ether);
        // We need to set block.number; roll to the given number
        vm.roll(blockNumber);
        // Call fallback with exactly 10 ether
        (bool success,) = address(c).call{value: 10 ether}("");
        assertTrue(success);
        uint after = c.pastBlockTime();
        // The reference updates pastBlockTime on success; mutant does not.
        // So the rule: after a successful fallback that does not trigger the transfer, pastBlockTime must increase.
        assertTrue(after > before);
    }
}

