pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _timestamp1, uint256 _timestamp2, uint256 _blockNumber1, uint256 _blockNumber2) public {
        // Bound timestamps to realistic values and ensure order
        _timestamp1 = bound(_timestamp1, 1, 1000000);
        _timestamp2 = bound(_timestamp2, 1, 1000000);
        _blockNumber1 = bound(_blockNumber1, 1, 1000000);
        _blockNumber2 = bound(_blockNumber2, 1, 1000000);

        // Ensure first timestamp is strictly less than second to create a valid sequence
        vm.assume(_timestamp1 < _timestamp2);

        // First successful call
        vm.warp(_timestamp1);
        vm.roll(_blockNumber1);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        vm.assume(success1);

        uint256 beforePastBlockTime = c.pastBlockTime();

        // Second call at same timestamp (should revert in reference, succeed in mutant)
        vm.warp(_timestamp2);
        vm.roll(_blockNumber2);
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // If the second call reverted, pastBlockTime must be unchanged
        if (!success2) {
            assertTrue(c.pastBlockTime() == beforePastBlockTime);
        }
    }
}

