pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_sol.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 blockNumber, uint8 seed, bool sendValue) public {
        // Bind to reasonable values
        timestamp = bound(timestamp, 1, type(uint40).max);
        blockNumber = bound(blockNumber, 1, 1000);

        // Set block info
        vm.warp(timestamp);
        vm.roll(blockNumber);

        // Optionally fund the contract
        vm.deal(address(c), 10 ether);

        // Record pastBlockTime before call
        uint256 before = c.pastBlockTime();

        // Make the call
        (bool success, ) = address(c).call{value: sendValue ? 10 ether : 0 ether}("");

        uint256 after = c.pastBlockTime();

        // General rule: after a successful call with correct value, pastBlockTime == block.timestamp
        // after any revert, pastBlockTime unchanged
        if (success && sendValue) {
            assertTrue(after == timestamp, "After success: pastBlockTime should equal block.timestamp");
        } else {
            assertTrue(after == before, "After revert: pastBlockTime should remain unchanged");
        }
    }
}

