pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 blockOffset) public {
        amount = bound(amount, 0, 100 ether);
        blockOffset = bound(blockOffset, 0, 100);

        // Skip direct 1 ether value that triggers the mutant's bypass
        vm.assume(amount != 1 ether);

        // Record block number for later check
        uint256 blockNumBefore = block.number;
        vm.roll(block.number + blockOffset);

        // Ensure timestamp is increasing
        vm.warp(c.pastBlockTime() + 1);

        // Fund contract
        vm.deal(address(c), amount);

        // Call fallback with value that reference requires (10 ether) to succeed
        (bool success, ) = address(c).call{value: 10 ether}("");

        // The reference succeeds if block.timestamp > pastBlockTime and msg.value == 10 ether
        // The mutant succeeds if block.timestamp > pastBlockTime and msg.value == 1 ether
        // Since we gave 10 ether, reference always succeeds, mutant reverts from require

        // After call, if block.number % 15 == 0, any balance should be transferred out
        // So for the reference, balance is either 0 or amount + 10 ether
        // For the mutant, the call reverts so balance stays at amount

        bool isDivisibleBlock = (block.number % 15 == 0);
        if (isDivisibleBlock && success) {
            assertTrue(address(c).balance == 0 ether);
        } else if (!success) {
            // Mutant reverts, balance unchanged
            assertTrue(address(c).balance == amount);
        } else {
            // Not divisible block, balance increased by 10 ether
            assertTrue(address(c).balance >= amount);
        }
    }
}

