pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value, uint256 blockOffset) public {
        // Bound blockOffset to ensure block.number can be set appropriately
        value = bound(value, 1 ether, 100 ether);
        blockOffset = bound(blockOffset, 0, 100);

        // First call to set pastBlockTime
        vm.deal(address(this), value);
        (bool success1, ) = address(c).call{value: value}("");

        // Second call with specific value and block manipulation
        vm.roll(block.number + 1 + blockOffset);
        vm.deal(address(this), value);
        (bool success2, ) = address(c).call{value: value}("");

        // Only check the rule if both calls succeeded and value == 10 ether
        vm.assume(success1 && success2);
        vm.assume(value == 10 ether);

        // Check if block.number % 15 == 0 after the second fallback
        // The rule: when block.number % 15 == 0 and the call value is 10 ether, 
        // the contract balance must be a multiple of 10 ether
        uint256 balance = address(c).balance;
        bool balanceIsMultipleOf10 = balance % 10 ether == 0;

        // If block.number % 15 == 0, then balance must be multiple of 10 ether
        assertTrue(!(block.number % 15 == 0) || balanceIsMultipleOf10);
    }
}

