pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        // Ensure timestamps are increasing
        vm.assume(timestamp2 > timestamp1);
        vm.assume(timestamp1 > 0);

        // Warp to timestamp1 and call fallback with 10 ether (first call always succeeds)
        vm.warp(timestamp1);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Warp to timestamp2 and try fallback with 1 ether
        vm.warp(timestamp2);
        vm.deal(address(this), 1 ether);
        (bool success2, ) = address(c).call{value: 1 ether}("");

        // In reference: 1 ether call reverts (success2 false). In buggy: may succeed.
        // If second call succeeded (bug), the balance increases by 1 ether.
        // After a failed call, the balance should remain unchanged for the next fallback.

        // Now make a third fallback call with 10 ether at a later timestamp
        vm.warp(timestamp2 + 1);
        vm.deal(address(this), 10 ether);
        (bool success3, ) = address(c).call{value: 10 ether}("");

        // The rule: If the second call reverted (reference behavior), the third call should succeed.
        // If the second call succeeded (bug), it may change the state unexpectedly.
        // The invariant: after any revert in the middle, the contract can still accept 10 ether.
        assertTrue(!success2 || success3);
    }
}

