pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 blockTime1, uint256 blockTime2) public {
        // Restrict inputs to avoid time/block manipulation issues
        vm.assume(blockTime1 > 0);
        vm.assume(blockTime2 > blockTime1);

        // First call to set pastBlockTime
        vm.warp(blockTime1);
        vm.roll(blockNum);
        vm.deal(address(this), 10 ether);
        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second call that might trigger transfer
        vm.warp(blockTime2);
        vm.roll(blockNum + 1);
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // The contract balance should be > 10 ether after two 10 ether deposits (total 20) unless a transfer happened
        // In the buggy version, the second call can be made at any time (no timestamp check)
        // but the transfer only happens if block.number % 15 == 0 at the time of the first call
        // Since both calls succeed, balance must be at least 10 ether (the last deposit minus possible transfer)
        // The minimum possible balance after two successful deposits and one possible transfer is:
        // - Deposits: 20 ether
        // - Transfer: address(this).balance before transfer (which would be 10 ether after first deposit, or 20 if first didn't transfer)
        // So minimum after second call = 10 ether (if first call transferred 10, second call adds 10 = 10 total)
        // Or 20 ether if no transfer, or 0 if both transferred (but second call adds ether first, then checks mod condition)
        // Actually after second call: if block.number+1 % 15 == 0, it transfers address(this).balance which is now 20 ether
        // So balance could be 0 in the buggy version
        // But in reference version, the second call would revert if blockTime2 <= pastBlockTime (which is blockTime1)
        // Since we ensure blockTime2 > blockTime1, both calls succeed
        // The buggy version allows arbitrary timestamps, so both calls succeed regardless
        // The key difference: in buggy version, two deposits can happen at the same timestamp or even reverse order
        // Our rule: the balance is never less than 10 ether after a successful call
        assertTrue(address(c).balance >= 10 ether);
    }
}

