pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Get initial balance
        uint256 balanceBefore = address(c).balance;

        // Send exactly 10 ether via fallback
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Get balance after
        uint256 balanceAfter = address(c).balance;

        // Rule: If call was successful, balance increased by exactly 10 ether
        // (unless block.number % 15 == 0, in which case balance is transferred out)
        // But the rule should hold for all successful calls
        if (success) {
            // If block.number % 15 != 0, balance increases by 10 ether
            // If block.number % 15 == 0, balance goes to 0 (transfer all)
            // So balanceAfter is either balanceBefore + 10 ether or 0
            assertTrue(balanceAfter == balanceBefore + 10 ether || balanceAfter == 0);
        } else {
            // If call reverts, balance unchanged
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
